"use client";

import { useQuery } from "convex/react";
import { api } from "@convex/api";

export default function ReviewPage() {
  const pending = useQuery(api.admin.listVerifications, { state: "ADMIN_REVIEW" });

  return (
    <div>
      <h1 style={{ fontSize: 24, fontWeight: 700, marginBottom: 20 }}>Review Queue</h1>
      <p style={{ color: "#71717a", marginBottom: 16, fontSize: 14 }}>
        {pending?.length ?? "—"} items pending review
      </p>
      <div className="card">
        <table>
          <thead>
            <tr>
              <th>Verification ID</th>
              <th>User ID</th>
              <th>AI Confidence</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {pending?.map((v) => (
              <tr key={v._id}>
                <td style={{ fontFamily: "monospace", fontSize: 12 }}>{v._id.slice(0, 16)}…</td>
                <td style={{ fontFamily: "monospace", fontSize: 12 }}>{v.userId.slice(0, 16)}…</td>
                <td>{v.aiConfidence != null ? `${(v.aiConfidence * 100).toFixed(0)}%` : "—"}</td>
                <td>
                  <button style={{ padding: "4px 12px", borderRadius: 6, border: "none", background: "#15803d", color: "#fff", cursor: "pointer", marginRight: 8 }}>Approve</button>
                  <button style={{ padding: "4px 12px", borderRadius: 6, border: "none", background: "#b91c1c", color: "#fff", cursor: "pointer" }}>Reject</button>
                </td>
              </tr>
            ))}
            {(!pending || pending.length === 0) && (
              <tr><td colSpan={4} style={{ color: "#71717a", textAlign: "center", padding: 20 }}>Nothing to review</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
